// Virtualized grid with performant updates
class VirtualizedGrid {
  constructor(container, data) {
    this.container = container;
    this.data = data;
 this.visibleItems = [];
    this.itemHeight = 50;
    this.bufferSize = 5;

    this.setupGrid();
    this.bindEvents();
  }

  setupGrid() {
    this.container.style.display = 'grid';
    this.container.style.gridTemplateColumns = 'repeat(auto-fit, minmax(200px, 1fr))';
    this.container.style.gap = '16px';
    this.container.style.height = '400px';
    this.container.style.overflow = 'auto';
  }

  updateVisibleItems() {
    const scrollTop = this.container.scrollTop;
    const containerHeight = this.container.clientHeight;
    const startIndex = Math.max(0, Math.floor(scrollTop / this.itemHeight) - this.bufferSize);
    const endIndex = Math.min(this.data.length, Math.ceil((scrollTop + containerHeight) / this.itemHeight) + this.bufferSize);

    requestAnimationFrame(() => {
      this.renderItems(startIndex, endIndex);
    });
  }

  renderItems(startIndex, endIndex) {
    const fragment = document.createDocumentFragment();

    // Clear existing items
    this.container.innerHTML = '';

    // Render visible items
    for (let i = startIndex; i < endIndex; i++) {
      const item = this.createItem(this.data[i], i);
      fragment.appendChild(item);
    }

    this.container.appendChild(fragment);
  }

  createItem(data, index) {
    const item = document.createElement('div');
    item.className = 'grid-item';
    item.textContent = data.title;
    item.style.transform = `translateY(${index * this.itemHeight}px)`;
    item.style.transition = 'transform 0.3s ease';

    // Use transform for position changes (GPU accelerated)
    item.addEventListener('click', () => {
      item.style.transform = `translateY(${index * this.itemHeight}px) scale(1.05)`;
      setTimeout(() => {
        item.style.transform = `translateY(${index * this.itemHeight}px) scale(1)`;
      }, 200);
    });

    return item;
  }

  bindEvents() {
    this.container.addEventListener('scroll', () => {
      this.updateVisibleItems();
    });

    window.addEventListener('resize', () => {
      this.updateVisibleItems();
    });
  }

  // Batch update for large datasets
  updateData(newData) {
    this.data = newData;

    // Use requestAnimationFrame for smooth updates
    requestAnimationFrame(() => {
      this.updateVisibleItems();
    });
  }

  // Reorder items with animation
  reorderItems(fromIndex, toIndex) {
    const item = this.data[fromIndex];
    this.data.splice(fromIndex, 1);
    this.data.splice(toIndex, 0, item);

    // Animate the reordering
    requestAnimationFrame(() => {
      this.updateVisibleItems();
    });
  }
}

// Performance monitoring
const performanceMonitor = {
  measureFPS() {
    let lastTime = performance.now();
    let frames = 0;

    function measure() {
      frames++;
      const currentTime = performance.now();

      if (currentTime >= lastTime + 1000) {
        const fps = Math.round((frames * 1000) / (currentTime - lastTime));
        console.log(`FPS: ${fps}`);
        frames = 0;
        lastTime = currentTime;
      }

      requestAnimationFrame(measure);
    }

    requestAnimationFrame(measure);
  }
};
```

## Why This Question Is Asked
This question tests your ability to combine multiple data sources (REST API and WebSocket) with caching and offline support. It checks if you understand how to coordinate asynchronous data streams while keeping the UI responsive.

## Key Concepts You Need to Show

### 1. Initial Data Loading (Fetch)
- Use fetch to get initial metrics from REST API
- Store results in memory (Map or Object keyed by id)
- Show loading state while fetching

### 2. Live Updates (WebSocket)
- Subscribe to WebSocket for real-time changes
- Apply incoming data diffs to your in-memory store
- **Schedule DOM updates** - batch updates using requestAnimationFrame or microtask queue to avoid blocking during message bursts
- Implement heartbeat/ping-pong to detect dead connections

### 3. Caching (Service Worker)
- **Stale-while-revalidate**: Check cache first, return cached response immediately, then fetch fresh data in background and update cache
- Use Cache API with appropriate cache names (versioned for updates)
- Handle offline scenarios gracefully

### 4. Offline Support & Reconnection
- Detect online/offline status via navigator.onLine and 'online'/'offline' events
- Queue failed requests and retry when connection restored
- **WebSocket reconnection with exponential backoff**: Start with short delay (e.g., 1s), double on each failure, cap at max (e.g., 30s), reset on successful connection

### 5. Performance Considerations
- Use requestAnimationFrame or setTimeout for batched DOM updates during WS message bursts
- Consider using Virtual DOM or only updating changed elements
- Debounce rapid updates if needed

## Service Worker Implementation (Stale-While-Revalidate)
```javascript
// sw.js
const CACHE_NAME = 'metrics-cache-v1';

self.addEventListener('fetch', (event) => {
  if (!event.request.url.includes('/api/metrics')) return;

  event.respondWith(
    caches.open(CACHE_NAME).then(async (cache) => {
      const cachedResponse = await cache.match(event.request);
      const fetchPromise = fetch(event.request).then((response) => {
        cache.put(event.request, response.clone());
        return response;
      }).catch(() => cachedResponse);
      return cachedResponse || fetchPromise;
    })
  );
});
```

## WebSocket Reconnection Logic
```javascript
class MetricsSocket {
  constructor(url) {
    this.url = url;
    this.reconnectDelay = 1000;
    this.maxReconnectDelay = 30000;
    this.connect();
  }

  connect() {
    this.ws = new WebSocket(this.url);
    this.ws.onclose = () => this.scheduleReconnect();
    this.ws.onpong = () => this.isAlive = true;
  }

  scheduleReconnect() {
    setTimeout(() => {
      this.reconnectDelay = Math.min(this.reconnectDelay * 2, this.maxReconnectDelay);
      this.connect();
    }, this.reconnectDelay);
  }

  startHeartbeat() {
    setInterval(() => {
      if (!this.isAlive) return this.ws.close();
      this.isAlive = false;
      this.ws.send(JSON.stringify({ type: 'ping' }));
    }, 30000);
  }
}
```

